"""Split closed binary artifacts into bounded, lossless parts; restore missing files only.

The original files are never removed or overwritten. Manifest paths are relative
to the growth study. Every part and whole file is verified before restoration.
"""

import argparse
import json
import os
from pathlib import Path
import tempfile
import time

from preserve_evidence import HERE, PHASE, digest, ignore_pattern, require, safe_path, sha, write_json


MAX_PART_BYTES = 512 * 1024
SCOPE = 'growth-followup-binary-artifacts'


def load_manifest(archive):
    path = archive / 'manifest.json'
    require(sha(path) == (archive / 'MANIFEST.sha256').read_text().strip(), 'Manifest checksum mismatch')
    value = json.loads(path.read_text())
    require(value['format'] == 1 and value['scope'] == SCOPE, 'Unexpected binary manifest')
    require(value['maximumPartBytes'] == MAX_PART_BYTES, 'Unexpected part bound')
    names = [entry['path'] for entry in value['files']]
    require(names and names == sorted(set(names)), 'Empty, duplicate or unsorted artifact paths')
    return value


def readback(archive, entry):
    data = bytearray()
    require(entry['parts'], 'Missing parts: ' + entry['path'])
    for part in entry['parts']:
        require(part['offset'] == len(data), 'Noncontiguous artifact parts')
        encoded = safe_path(archive, part['path']).read_bytes()
        require(len(encoded) == part['bytes'] and 0 < len(encoded) <= MAX_PART_BYTES,
                'Incorrect or oversized artifact part: ' + part['path'])
        require(digest(encoded) == part['sha256'], 'Artifact part checksum mismatch: ' + part['path'])
        data.extend(encoded)
    require(len(data) == entry['bytes'] and digest(data) == entry['sha256'],
            'Restored artifact checksum mismatch: ' + entry['path'])
    return data


def verify(archive, destination):
    manifest = load_manifest(archive)
    matched = 0
    for entry in manifest['files']:
        readback(archive, entry)
        target = safe_path(destination, entry['path'])
        if target.exists():
            require(target.is_file() and target.stat().st_size == entry['bytes']
                    and sha(target) == entry['sha256'], 'Refusing different existing bytes: ' + str(target))
            matched += 1
    return manifest, {'files': len(manifest['files']), 'bytes': sum(e['bytes'] for e in manifest['files']),
                      'parts': sum(len(e['parts']) for e in manifest['files']),
                      'existingMatched': matched, 'missingRestorable': len(manifest['files']) - matched}


def restore(archive, destination):
    # Validate every part and every existing target before creating any missing artifact.
    manifest, before = verify(archive, destination)
    restored = 0
    for entry in manifest['files']:
        target = safe_path(destination, entry['path'])
        if target.exists():
            require(target.is_file() and sha(target) == entry['sha256'],
                    'Refusing changed existing bytes: ' + str(target))
            continue
        target.parent.mkdir(parents=True, exist_ok=True)
        temporary = None
        try:
            with tempfile.NamedTemporaryFile(prefix='.binary-restore-', dir=target.parent, delete=False) as stream:
                temporary = Path(stream.name)
                stream.write(readback(archive, entry))
                stream.flush()
                os.fsync(stream.fileno())
            try:
                os.link(temporary, target)
                restored += 1
            except FileExistsError:
                require(target.is_file() and sha(target) == entry['sha256'],
                        'Refusing concurrently created different bytes: ' + str(target))
        finally:
            if temporary is not None:
                temporary.unlink()
    _, after = verify(archive, destination)
    return {**after, 'restored': restored, 'existingMatchedBeforeRestore': before['existingMatched']}


def preserve(output, names, append_ignore):
    require(output.is_relative_to(HERE), 'Keep preservation beneath this recovery directory')
    require(not output.exists(), 'Refusing to replace an existing archive: ' + str(output))
    require(names and len(names) == len(set(names)), 'Empty or duplicate source list')
    selected = [safe_path(PHASE, name) for name in sorted(names)]
    require(all(path.is_file() and path.stat().st_size > 0 for path in selected), 'Missing or empty source')
    require(all(not path.is_relative_to(output) for path in selected), 'Output cannot contain its inputs')
    ignore = PHASE / '.gitignore'
    ignore_before = ignore.read_bytes() if ignore.exists() else b''
    output.mkdir(parents=True)
    (output / 'objects').mkdir()
    records = []
    for index, source in enumerate(selected):
        before = source.stat()
        data = source.read_bytes()
        checksum = digest(data)
        parts = []
        for ordinal, offset in enumerate(range(0, len(data), MAX_PART_BYTES)):
            block = data[offset:offset + MAX_PART_BYTES]
            relative = f'objects/{index:03d}-{checksum[:16]}-{ordinal:03d}.bin'
            with (output / relative).open('xb') as stream:
                stream.write(block)
            parts.append({'path': relative, 'offset': offset, 'bytes': len(block), 'sha256': digest(block)})
        after = source.stat()
        require((before.st_ino, before.st_size, before.st_mtime_ns) ==
                (after.st_ino, after.st_size, after.st_mtime_ns) and sha(source) == checksum,
                'Source changed during preservation: ' + str(source))
        records.append({'path': source.relative_to(PHASE).as_posix(), 'bytes': len(data),
                        'sha256': checksum, 'parts': parts})
    manifest = {'format': 1, 'scope': SCOPE, 'createdEpochNs': time.time_ns(),
                'maximumPartBytes': MAX_PART_BYTES, 'rawFilesRemoved': False,
                'preserverSha256': sha(Path(__file__)),
                'commonHelperSha256': sha(HERE / 'preserve_evidence.py'), 'files': records}
    write_json(output / 'manifest.json', manifest)
    with (output / 'MANIFEST.sha256').open('x') as stream:
        stream.write(sha(output / 'manifest.json') + '\n')
    _, checked = verify(output, PHASE)
    require(checked['existingMatched'] == len(records), 'Original artifacts failed readback verification')
    addition = '\n# Binary artifacts preserved losslessly in recovery/' + output.name + '.\n'
    addition += ''.join(ignore_pattern(entry['path']) + '\n' for entry in records)
    with (output / 'ignore-append.txt').open('x') as stream:
        stream.write(addition)
    ignore_change = {'applied': False, 'exactPathCount': len(records)}
    if append_ignore:
        require(ignore.read_bytes() == ignore_before, 'Ignore file changed during preservation')
        with ignore.open('ab') as stream:
            stream.write(addition.encode())
        after = ignore.read_bytes()
        require(after == ignore_before + addition.encode(), 'Ignore append verification failed')
        ignore_change = {'applied': True, 'appendOnly': True, 'exactPathCount': len(records),
                         'beforeSha256': digest(ignore_before), 'afterSha256': digest(after)}
    result = {**checked, 'manifestSha256': sha(output / 'manifest.json'), 'rawFilesUnchanged': True,
              'largestPartBytes': max(p['bytes'] for e in records for p in e['parts']),
              'ignoreChange': ignore_change}
    write_json(output / 'verification.json', result)
    return result


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    commands = parser.add_subparsers(dest='command', required=True)
    create = commands.add_parser('preserve')
    create.add_argument('--file', action='append', required=True, help='Path relative to this study')
    create.add_argument('--output', type=Path, required=True)
    create.add_argument('--append-ignore', action='store_true')
    for name in ('verify', 'restore'):
        operation = commands.add_parser(name)
        operation.add_argument('--archive', type=Path, required=True)
        operation.add_argument('--destination', type=Path, default=PHASE)
    args = parser.parse_args()
    if args.command == 'preserve':
        result = preserve(args.output.resolve(), args.file, args.append_ignore)
    elif args.command == 'verify':
        _, result = verify(args.archive.resolve(), args.destination.resolve())
    else:
        result = restore(args.archive.resolve(), args.destination.resolve())
    print(json.dumps(result, indent=2, sort_keys=True))


if __name__ == '__main__':
    main()
